<script>
export default {
  props: [],
  emits: ['selectCar'],
  data() {
    return {
        cars: [
            {plate:"ABC 123", label:"T20"},
            {plate:"ABC 124", label:"T20"},
            {plate:"ABC 125", label:"T20"},
            {plate:"ABC 126", label:"T20"},
        ]
    }
  },
  methods: {
    async updateCars() {
        const response = await fetch(`https://${this.$getResource()}/getcars`);
        const allcars = await response.json();
        if (allcars) this.cars = allcars;
    },
    close() {
        fetch(`https://${this.$getResource()}/exit`);
        this.$emit('selectCar', false)
    },
    onmessage(event) {
        const eventType = event.data.action
        if (eventType == "show") {
            document.body.style.display = event.data.enable ? "block" : "none";
            if (event.data.enable) {
                this.$emit('selectCar', false)
                this.updateCars()
            }
        }
    }
  },
  created() {
    window.addEventListener('message', this.onmessage)
  }
}
</script>

<template>
  <div class="carmenu">
    <h2>Autó lista</h2>
    <button class="btn close-btn" @click="close()"><i class="bi bi-x-circle"></i></button>
    <button class="btn" @click="updateCars()"><i class="bi bi-arrow-repeat"></i> Frissítés</button>
    <div class="car-list" >
        <div class="row" style="font-size: 120%;">
            <div class="col">
                Rendszám
            </div>
            <div class="col">
                Név
            </div>
        </div>
        <div class="row" v-for="car in cars" :key="car.plate" @click="$emit('selectCar', car.plate)">
            <div class="col">
                {{car.plate}}
            </div>
            <div class="col">
                {{car.label}}
            </div>
        </div>
    </div>
  </div>
</template>

<style>
.carmenu {
    position: relative;
    width: 25%;
    height: 60%;

    background-color: #0e161f;

    border-radius: 10px;
    
    overflow-y: auto;
    overflow-x: hidden;
    font-family: 'Nunito', sans-serif;
    color: white;
    text-align: center;

    padding: 10px 10px 10px 10px;
}
.close-btn {
    position: absolute;
    top: 15px; 
    right: 15px; 
    font-size: 1.4rem;
}
.car-list {
    margin-top: 10px;
    margin-left: 50%;
    transform: translateX(-50%);
    width: 90%;
    display: flex;
    flex-direction: column;
    gap: 5px;
    overflow-y: auto;
    height: 80%;
}
.car-list .row {
    width: 100%;
    border-radius: 5px;
    display: flex;
    flex-direction: row;
    justify-content: center;
    align-items: center;
    background-color: #10253a;
    min-height: 8%;
    cursor: pointer;
} 
.car-list .col {
    width: 50%;
}
</style>