<script>
export default {
  props: ['selectedPlate'],
  emits: [],
  data() {
    return {
      alarmstate: false,
      alarmprice:0,
      alarmgpsprice:0
    }
  },
  methods: {
    async updateAlarm() {
        if (!this.selectedPlate) return
        const response = await fetch(`https://${this.$getResource()}/getalarm`, {
            method: 'POST',
            body: JSON.stringify({
                plate: this.selectedPlate
            })
        });
        const alarm = await response.json();
        this.alarmstate = alarm;
    },
    buyalarm(alarmtyp, bank){
      fetch(`https://${this.$getResource()}/buyalarm`, {
        method: 'POST',
        body: JSON.stringify({
          plate: this.selectedPlate,
          alarmtyp:alarmtyp,
          bank:bank
        })
      });
    },
    getpos() {
      fetch(`https://${this.$getResource()}/getpos`, {
        method: 'POST',
        body: JSON.stringify({
          plate: this.selectedPlate
        })
      });
    },
    removealarm() {
      fetch(`https://${this.$getResource()}/removealarm`, {
        method: 'POST',
        body: JSON.stringify({
          plate: this.selectedPlate
        })
      });
    },
  },
  watch: {
    selectedPlate: function() {
        this.updateAlarm()
    }
  },
  mounted() {
    this.updateAlarm()
  },
  async created() {
    const response = await fetch(`https://${this.$getResource()}/prices`);
    const prices = await response.json();
    if (prices) {
      this.alarmprice = prices.alarmprice;
      this.alarmgpsprice = prices.alarmgpsprice;
    }
  }
}
</script>

<template>
  <div class="alarmmenu">
    <h2>Riasztó kezelése</h2>
    <div class="alarmmenu-cont" v-if="selectedPlate">
        <div v-if="alarmstate">
            <p>{{alarmstate}}</p>
            <button class="btn" @click="getpos()">Autó pozíciójának bemérése</button> <br>
            <button class="btn" style="margin-top:15px;" @click="removealarm()">Riasztó kiszerelése</button>
        </div>
        <div v-else>
            <p>Nem található riasztó</p>
            <p>Riasztó - {{alarmprice}}$ <button class="btn" @click="buyalarm('alarm', false)"><i class="bi bi-cash-coin"></i> Készpénz</button> <button class="btn" @click="buyalarm('alarm', true)"><i class="bi bi-credit-card"></i> Bankkártya</button></p> 
            <p>Riasztó + GPS - {{alarmgpsprice}}$ <button class="btn" @click="buyalarm('alarmgps', false)"><i class="bi bi-cash-coin"></i> Készpénz</button> <button class="btn" @click="buyalarm('alarmgps', true)"><i class="bi bi-credit-card"></i> Bankkártya</button></p> 
        </div>
    </div>
    <h3 v-else>Nincs kiválasztott autó</h3>
  </div>
</template>

<style>
.alarmmenu {
    position: relative;
    width: 100%;
    height: 45%;

    background-color: #0e161f;

    border-radius: 10px;
    
    overflow-y: auto;
    overflow-x: hidden;
    font-family: 'Nunito', sans-serif;
    color: white;
    text-align: center;

    padding: 10px 10px 10px 10px;
}
.alarmmenu-cont {
    height: 70%;
}
</style>