<script>
export default {
  props: ['selectedPlate'],
  emits: [],
  data() {
    return {
        keys: [
            {label:"Kulcs 1", id:1},
            {label:"Kulcs 2", id:2},
        ]
    }
  },
  methods: {
    async updateKeys() {
        if (!this.selectedPlate) return
        const response = await fetch(`https://${this.$getResource()}/getkeys`, {
            method: 'POST',
            body: JSON.stringify({
                plate : this.selectedPlate
            })
        });
        const allcars = await response.json();
        if (allcars) this.keys = allcars;
    },
    deletekey(kid) {
        fetch(`https://${this.$getResource()}/delkey`, {
            method: 'POST',
            body: JSON.stringify({
                plate : this.selectedPlate,
                kid:kid
            })
        });
    }
  },
  watch: {
    selectedPlate: function() {
        this.updateKeys()
    }
  },
  mounted() {
    this.updateKeys()
  }
}
</script>

<template>
  <div class="keymenu">
    <h2>Kulcs lista</h2>
    <div class="key-cont" v-if="selectedPlate">
        <h3>Autó: {{selectedPlate}}</h3>
        <button class="btn" @click="updateKeys()"><i class="bi bi-arrow-repeat"></i> Frissítés</button>
        <div class="key-list" >
            <div class="row">
                <div class="col">
                    Név
                </div>
                <div class="col">
                    ID
                </div>
                <div class="col">
                    Törlés
                </div>
            </div>
            <div class="row" v-for="key in keys" :key="key.id">
                <div class="col">
                    {{key.label}}
                </div>
                <div class="col">
                    {{key.id}}
                </div>
                <div class="col">
                    <button class="btn" @click="deletekey(key.id)"><i class="bi bi-trash"></i> Törlés</button>
                </div>
            </div>
        </div>
    </div>
    <h3 v-else>Nincs kiválasztott autó</h3>
  </div>
</template>

<style>
.keymenu {
    position: relative;
    width: 25%;
    height: 60%;

    background-color: #0e161f;

    border-radius: 10px;
    
    overflow-y: auto;
    overflow-x: hidden;
    font-family: 'Nunito', sans-serif;
    color: white;
    text-align: center;

    padding: 10px 10px 10px 10px;
}
.key-cont {
    height: 80%;
}
.key-list {
    margin-top: 10px;
    margin-left: 50%;
    transform: translateX(-50%);
    width: 90%;
    display: flex;
    flex-direction: column;
    gap: 5px;
    overflow-y: auto;
    height: 80%;
}
.key-list .row {
    width: calc(100%-6px);
    border-radius: 5px;
    display: flex;
    flex-direction: row;
    justify-content: center;
    align-items: center;
    background-color: #10253a;
    min-height: 8%;
    cursor: pointer;
    padding: 3px;
} 
.key-list .col {
    width: 33%;
}
.key-list .btn {
    background-color: #0e161f;
}
</style>