<template>
  <CarList @selectCar="selectPlate"/>
  <KeyList :selectedPlate="plate" />
  <div class="last-section">
    <NewKey :selectedPlate="plate" />
    <AlarmMenu :selectedPlate="plate" />
  </div>
</template>

<script>
import CarList from './components/CarList.vue'
import KeyList from './components/KeyList.vue'
import NewKey from './components/NewKey.vue'
import AlarmMenu from './components/AlarmMenu.vue'
export default {
  name: 'App',
  components: {
    CarList,
    KeyList,
    NewKey,
    AlarmMenu
  },
  data() {
    return {
      plate : false
    }
  },
  methods: {
    selectPlate(plate) {
      if (plate == this.plate) {
        this.plate = false 
      } else {
        this.plate = plate
      }
    },
    onkey(evt) {
      evt = evt || window.event;
      if (evt.keyCode == 27) {
        this.plate = false 
        fetch(`https://${this.$getResource()}/exit`);
      }
    }
  },
  created() {
    document.onkeydown = this.onkey
  }
}
</script>

