<script>
export default {
  props: ['selectedPlate'],
  emits: [],
  data() {
    return {
       label : null,
       price:0
    }
  },
  methods: {
    buynewkey(bank) {
      fetch(`https://${this.$getResource()}/newkey`, {
        method: 'POST',
        body: JSON.stringify({
          plate : this.selectedPlate,
          label:this.label,
          bank:bank
        })
      });
    }
  },
  async created() {
    const response = await fetch(`https://${this.$getResource()}/prices`);
    const prices = await response.json();
    if (prices) this.price = prices.newkey;
  }
}
</script>

<template>
  <div class="newkey">
    <h2>Új kulcs létrehozása</h2>
    <div class="newkey-cont" v-if="selectedPlate">
        <p>{{price}}$</p>
        <input class="txt-inp" type="text" v-model="label" placeholder="Kulcs neve"> <br>
        <button class="btn" @click="buynewkey(false)"><i class="bi bi-cash-coin"></i> Fizetés készpézzel</button> <br>
        <button class="btn" @click="buynewkey(true)"><i class="bi bi-credit-card"></i> Fizetés bankkártyával</button>
    </div>
    <h3 v-else>Nincs kiválasztott autó</h3>
  </div>
</template>

<style>
.newkey {
    position: relative;
    width: 100%;
    height: 45%;

    background-color: #0e161f;

    border-radius: 10px;
    
    overflow-y: auto;
    overflow-x: hidden;
    font-family: 'Nunito', sans-serif;
    color: white;
    text-align: center;

    padding: 10px 10px 10px 10px;
}
.newkey-cont {
    height: 70%;
}
.newkey-cont * {
    margin-top: 15px;
}
</style>